    param(
        [ValidateSet("Chrome", "Firefox", "Edge", "All")]
        [string]$Browser = "All",
        [int]$Limit = 100
    )

    $history = @()

    if ($Browser -eq "Chrome" -or $Browser -eq "All") {
        $chromePath = "$env:LOCALAPPDATA\Google\Chrome\User Data\Default\History"
        if (Test-Path $chromePath) {
